	public static void writeString(String s, StringBuilder sb) {
		sb.append('"');
		int start = 0;
		int length = s.length();
		for (int i = 0; i < length; i++) {
			char c = s.charAt(i);
			String escape = null;
			switch (c) {
			case '"':
				escape = "\\\"";
				break;
			case '\\':
				escape = "\\\\";
				break;
			case '\n':
				escape = "\\n";
				break;
			case '\r':
				escape = "\\r";
				break;
			case '\t':
				escape = "\\t";
				break;
			case '\b':
				escape = "\\b";
				break;
			case '\f':
				escape = "\\f";
				break;
			default:
				if (c < 0x20) {
					escape = String.format("\\u%04x", (int) c);
				}
			}
			if (escape != null) {
				sb.append(s, start, i).append(escape);
				start = i + 1;
			}
		}
		sb.append(s, start, length).append('"');
	}

